pat='_TUVTR_WU_UXVN_Y'
def fill(o):
    it=iter(o); return ''.join(next(it) if c=='_' else c for c in pat)
def ok(s):
    b=[s[i:i+4] for i in range(0,16,4)]
    step=lambda xs,d:all(ord(y)-ord(x)==d for x,y in zip(xs,xs[1:]))
    return step([x[0] for x in b],1) and step([x[1] for x in b],-2) and step([x[2] for x in b],0) and step([x[3] for x in b],1)
opts={'A':'SUUP','B':'SUPU','C':'PSVU','D':'SVUP'}
assert [k for k,v in opts.items() if ok(fill(v))]==['B']

